test "every API entry is ported" {
    inline for (@typeInfo(Entry).@"enum".field_values) |field_value| {
        const entry: Entry = @fromBackingInt(@intCast(field_value));
        try std.testing.expectEqual(Coverage.ported, coverage(entry));
    }
}

/// One entry's chaining counts, checked in a block of its own.
///
/// **Why the sweep is a call and not an inlined body.** Zig charges every
/// comptime loop iteration and every `if` in a swept body as a backwards
/// branch against the block being evaluated, and the quota is 1000. `Entry`
/// has 347 members, so the loop and the `if` inside it spend 694 branches
/// before the last third of the table is reached. A call per entry gives each
/// entry a fresh block, and the loop body below is the one call.
fn expectEntryChaining(entry: Entry) !void {
    const counts = record(entry);
    try std.testing.expectEqual(counts.chain_members, counts.extension_slots);
    if (!counts.extensible) {
        try std.testing.expectEqual(0, counts.extension_slots);
    }
}

test "a chained struct belongs to a root and an extension to none" {
    inline for (@typeInfo(Entry).@"enum".field_values) |field_value| {
        try expectEntryChaining(@fromBackingInt(@intCast(field_value)));
    }
}

test "the per-entry table sums to the totals" {
    var methods: usize = 0;
    var members: usize = 0;
    inline for (@typeInfo(Entry).@"enum".field_values) |field_value| {
        const entry: Entry = @fromBackingInt(@intCast(field_value));
        methods += record(entry).methods;
        members += record(entry).members;
    }
    try std.testing.expectEqual(method_count, methods);
    try std.testing.expectEqual(member_count, members);
}
